```bash
cd /home/vscode/nullness-benchmarks/libgdx && sed -i '987,990c\      @Nullable Actor a = c.actor;
      if (a == null) continue;
      Actor actorNonNull = a;
      float minWidth = c.minWidth.get(actorNonNull),
          prefWidth = c.prefWidth.get(actorNonNull),
          maxWidth = c.maxWidth.get(actorNonNull);' gdx/src/com/badlogic/gdx/scenes/scene2d/ui/Table.java && nl -ba gdx/src/com/badlogic/gdx/scenes/scene2d/ui/Table.java | sed -n '979,1002p' && ./gradlew gdx:compileJava -x test > new_build_output.log 2>&1 && tail -n 40 new_build_output.log
```

